// 把上游(v1-router / api-proxy)返回的原始错误体翻译成干净、可执行的中文提示，
// 避免把 {"ok":false,"error":"no_available_account",...} 这种嵌套 JSON 直接甩给用户。

function humanizeUpstreamError(rawText, { status, model, provider } = {}) {
  const raw = normalizeString(rawText);
  let payload = null;
  if (raw) {
    try {
      payload = JSON.parse(raw);
    } catch (_error) {
      const jsonMatch = raw.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try { payload = JSON.parse(jsonMatch[0]); } catch (_e) { payload = null; }
      }
    }
  }

  // Some gateway/Go boundaries wrap the original JSON in `detail` (for
  // example `{error:"upstream_503", detail:"{...}"}`). Unwrap that layer
  // before selecting a user-facing message so desktop translation never shows
  // an internal error envelope as the result.
  if (payload && typeof payload.detail === 'string') {
    const nestedText = normalizeString(payload.detail);
    try {
      const nested = JSON.parse(nestedText);
      if (nested && typeof nested === 'object') {
        payload = { ...nested, ...payload, ...(nested.error ? { error: nested.error } : {}) };
      }
    } catch (_error) {
      const nestedMatch = nestedText.match(/\{[\s\S]*\}/);
      if (nestedMatch) {
        try {
          const nested = JSON.parse(nestedMatch[0]);
          if (nested && typeof nested === 'object') {
            payload = { ...nested, ...payload, ...(nested.error ? { error: nested.error } : {}) };
          }
        } catch (_nestedError) { /* retain the outer payload */ }
      }
    }
  }

  const innerError = payload && typeof payload.error === 'object' ? payload.error : null;
  const code = payload && typeof payload.error === 'string' ? payload.error : (innerError && innerError.code || innerError && innerError.type || '');
  const detail = payload
    ? normalizeString(payload.detail || payload.message || payload.reason || (innerError && (innerError.message || innerError.detail)))
    : '';
  const modelLabel = normalizeString(model);
  const providerLabel = normalizeString(provider);
  const modelText = modelLabel ? `「${modelLabel}」` : '';
  const providerText = providerLabel ? `${providerLabel} ` : '';

  switch (code) {
    case 'no_available_account':
      // 说明当前 AIH 的接入范围，不把 relay 策略说成厂商 OAuth 的能力限制。
      const familyProvider = modelLabel.toLowerCase().startsWith('gemini') || modelLabel.toLowerCase().startsWith('agy')
        ? 'agy'
        : providerLabel.toLowerCase();
      if (familyProvider === 'agy') {
        return `模型${modelText || ''}暂时不可用。请刷新模型目录或同步 AWS Server 的 AGY 账号；这不是 Codex 账号缺失。`;
      }
      if (providerLabel.toLowerCase() === 'zcode') {
        return '当前 AIH 没有可用于该模型的 ZCode 推理账号。ZCode OAuth 账号在 AIH 中用于账号管理、桌面启动和用量查询；网关推理请使用已配置且可用的 Coding Plan API Key 账号，或切换其他账号/模型。';
      }
      {
        // The gateway reports which pool it actually searched and why nothing was
        // eligible. Say that, instead of guessing from the provider the user picked
        // (which is often not the pool the model routed to).
        const availability = payload && payload.availability && typeof payload.availability === 'object'
          ? payload.availability : null;
        const poolProvider = normalizeString(availability && availability.provider) || providerLabel;
        const total = Number(availability && availability.total);
        const reason = normalizeString(availability && availability.reason);
        const poolText = poolProvider ? `${poolProvider} ` : '';
        if (availability && Number.isFinite(total) && total > 0) {
          const why = reason === 'no_eligible_account'
            ? `这 ${total} 个账号都不提供该模型，或正在冷却 / 已停用`
            : `这 ${total} 个账号当前都不可用${reason ? `（${reason}）` : ''}`;
          return `模型${modelText || ''}被路由到 ${poolText}账号池，但${why}。请改用账号目录里有的模型，或在「账号」页确认该模型对应的账号可用。`;
        }
        if (availability && Number.isFinite(total) && total === 0) {
          return `模型${modelText || ''}被路由到 ${poolText}账号池，但当前 server 上没有任何 ${poolText}账号。请先在「账号」页添加，或改用其他模型。`;
        }
        return (
          `当前 server 上没有可用于模型${modelText || ''}的${providerText}账号。`
          + `可能原因：该账号未在此 server 完成登录/凭据配置，或该模型未在账号的可用清单里。`
          + `请在「账号」页补全该 server 上的账号凭据，或改用其他账号/模型后重试。`
        );
      }
    case 'account_not_configured':
      return (
        `所选${providerText}账号在当前 server 上尚未完成配置(缺少登录凭据)。`
        + `请先在「账号」页为该 server 补全登录后再发送。`
      );
    case 'missing_model':
    case 'model_required':
      return '请先选择一个模型再发送。';
    case 'model_not_found':
      return `模型${modelText || ''}在当前 server 上不可用，请改用其他模型。`;
    case 'rate_limited':
    case 'cooldown':
      return (
        `该${providerText}账号当前被上游限流/熔断${detail ? `（${detail}）` : ''}。`
        + `请稍后重试，或改用其他账号。`
      );
    default:
      break;
  }

  if (detail) {
    const cleanDetail = detail.replace(/^(?:Error:\s*)+/i, '');
    if (cleanDetail === 'Internal server error' || cleanDetail.toLowerCase() === 'internal server error') {
      return `上游服务暂时发生内部错误（Internal server error），请稍后重试或切换其他模型。`;
    }
    if (/^upstream_\d+\s*:/i.test(cleanDetail)) {
      return status >= 500
        ? '翻译上游暂时不可用，请在高级设置中刷新模型目录或切换模型。'
        : '翻译请求未被上游接受，请在高级设置中检查模型和路由。';
    }
    return cleanDetail;
  }

  if (raw && !payload) return raw;

  if (status === 500) {
    return '上游模型服务发生 500 内部错误，请稍后重试或切换模型。';
  }
  if (status) return `请求失败（HTTP ${status}）`;
  return '请求失败';
}


function attachAbortableRequestClose(req, onClose, res) {
  if (typeof onClose !== 'function') return () => {};
  let attached = false;
  if (req && typeof req.on === 'function') {
    req.on('close', onClose);
    req.on('aborted', onClose);
    attached = true;
  }
  if (res && typeof res.on === 'function') {
    res.on('close', onClose);
    attached = true;
  }
  return attached ? onClose : () => {};
}


